/**
 * Substantive default content added by the library content pass (see `catalogue/standards.ts` and `scripts/audit-pb-library.ts`).
 * Each entry adds real sections to a template that was below the industry standard for its kind of document. Rules: full sentences, written for
 * the document type; every changeable fact is a declared input variable; no figures, rates, wages, penalties or section numbers of any law are
 * stated (laws are named only where the document must refer to them); no placeholders other than declared inputs. Line syntax: "- " starts a bullet,
 * "TABLE w1,w2 ;; Head A|Head B ;; cell|cell" is a table (widths in percent, first row is the header), anything else is a paragraph.
 */
import { bullets, p, table } from "@/lib/products/playbook-ai/catalogue/build";
import type { RawBlock, TemplateDef, TemplateSection } from "@/lib/products/playbook-ai/catalogue/types";

export type Add = [at: string, key: string, title: string, ...lines: string[]];

function blocks(lines: string[]): RawBlock[] {
  const out: RawBlock[] = [];
  let list: string[] = [];
  const flush = () => { if (list.length) { out.push(bullets(list)); list = []; } };
  for (const l of lines) {
    if (l.startsWith("- ")) { list.push(l.slice(2)); continue; }
    flush();
    if (l.startsWith("TABLE ")) {
      const [head, ...rows] = l.slice(6).split(" ;; ");
      const widths = head.split(",").map(Number);
      const [h, ...body] = rows.map((r) => r.split("|").map((c) => c.trim()));
      out.push(table(widths, h, body));
    } else out.push(p(l));
  }
  flush();
  return out;
}

export const EXPAND: Record<string, Add[]> = {};

export function applyExpand(def: TemplateDef): TemplateDef {
  const adds = EXPAND[def.id];
  if (!adds) return def;
  let sections = [...def.sections];
  for (const [at, key, title, ...lines] of adds) {
    const sec: TemplateSection = { key, title, aiMode: "fixed", locked: false, body: blocks(lines) };
    if (at === "start") { const i = sections.findIndex((s) => !s.draftOnly); sections.splice(i < 0 ? sections.length : i, 0, sec); }
    else if (at.startsWith("after:")) { const i = sections.findIndex((s) => s.key === at.slice(6)); sections.splice(i < 0 ? sections.length : i + 1, 0, sec); }
    else {
      const i = sections.findIndex((s) => JSON.stringify(s.body).includes('"signatureBlock"'));
      sections.splice(i < 0 ? sections.length : i, 0, sec);
    }
  }
  return { ...def, sections };
}

